// ADR-0027: the warm voice says the same thing as the phone's voice, without the name, and
// every clip it can ask for exists in /voice/ (generated by scripts/gen-voice.ts).
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import { allClips, clipsFor, KM, METERS } from "../../src/lib/compass/voice.ts";

const STATIC = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../../static/voice");
const manifest = JSON.parse(fs.readFileSync(path.join(STATIC, "manifest.json"), "utf8")) as {
  meters: number[];
  km: number[];
  clips: Record<string, { file: string; text: string }>;
};

describe("warm voice clips (ADR-0027)", () => {
  it("rounds to a recorded distance and adds the direction", () => {
    expect(clipsFor("pointing", 147, -30, false)).toEqual(["m-150", "dir-slightLeft"]);
    expect(clipsFor("pointing", 3, 90, false)).toEqual(["m-5", "dir-right"]);
    expect(clipsFor("pointing", 980, 170, false)).toEqual(["m-950", "dir-behind"]);
    expect(clipsFor("pointing", 2300, -60, false)).toEqual(["km-2_5", "dir-left"]);
  });
  it("says straight ahead when facing, close when near, and hold flat with no heading", () => {
    expect(clipsFor("facing", 200, 4, true)).toEqual(["ahead"]);
    expect(clipsFor("pointing", 200, 10, false)).toEqual(["ahead"]);
    expect(clipsFor("near", 8, 0, false)).toEqual(["close"]);
    expect(clipsFor("no-orientation", 60, 0, false)).toEqual(["m-60", "flat"]);
    expect(clipsFor("no-gps", 0, 0, false)).toEqual(["nogps"]);
  });
  it("matches the generator's buckets, and every clip shipped", () => {
    expect(manifest.meters).toEqual(METERS);
    expect(manifest.km).toEqual(KM);
    for (const id of allClips()) {
      expect(manifest.clips[id], id).toBeTruthy();
      expect(fs.existsSync(path.join(STATIC, `${id}.mp3`)), id).toBe(true);
    }
  });
  it("never records a name or a place: every clip's words come from the fixed deck lines", () => {
    for (const { text } of Object.values(manifest.clips)) expect(text).toMatch(/^[A-Za-z0-9 .,'’]+$/);
    expect(Object.keys(manifest.clips).length).toBe(allClips().length);
  });
});
